# coding: utf-8
from lesson_authoring import entry as E
A=[['希腊 aer → 拉丁 aer','空气']]
B=[['希腊 aer 空气 + bios 生命','近代学术构词材料'],['法语 aérobie → 英语 aerobic','依赖氧而生存的 → 有氧的']]
W=[
E('aerate','英 /ˈeəreɪt/；美 /ˈereɪt/','使空气进入；给……通气','松开板结的土，或往水里鼓气，让空气有机会进去。','aer- 空气 + 动词形式 -ate；历史可能由较早的 aeration 逆构，也受法语 aérer 影响。',A+[['法语 aérer／aération','使通气／通气'],['英语 aeration → aerate〔可能的逆构路线〕','通气这个过程 → 使通气']],'aerate the soil 是让空气更容易进入土中；aerate water 是把空气混入水里。动作可以靠打孔、松动或鼓气实现，不是只把东西放在天空下面。','aerate the soil；aerate water；aerate a lawn。','aerate 强调空气进入材料或液体，ventilate 常强调室内等空间的空气流通与换气。两者有关，但对象和侧重点不同。',('The gardener used a fork to aerate the soil.','园丁用叉子松土，让空气进去。'),('A small pump aerates the water in the tank.','一个小泵向水箱中的水充气。'),sources=['https://www.etymonline.com/word/aerate','https://www.oxfordlearnersdictionaries.com/definition/english/aerate']),
E('aeration','英 /eəˈreɪʃən/；美 /eˈreɪʃən/','通气；曝气；使空气混入的过程','把空气带进去这一整件事：土壤里有气路，水里冒出细泡。','现代可对应 aerate + -ion；较早英语名词来自法语 aération，不能把所有用法都倒画成英语 aerate 的后代。',A+[['法语 aérer → aération','使通气 → 通气过程'],['英语 aeration','通气；使空气与水、土等接触或混合']],'soil aeration 说土壤通气状况或改善通气的过程；water aeration 可指向水中引入空气。中文“曝气”比较专业，理解时先抓住“把空气送进去”。','soil aeration；water aeration；an aeration system；improve aeration。','aeration 是过程，aerator 才是相关装置或工具。名词看起来更长，不代表一定比同族动词出现得晚。',('Heavy machinery can reduce soil aeration by compacting the ground.','重型机械压实地面，会降低土壤的通气性。'),('The tank has an aeration system that releases small bubbles.','水箱装有一个释放小气泡的曝气系统。'),sources=['https://www.etymonline.com/word/aerate','https://www.oxfordlearnersdictionaries.com/definition/english/aeration']),
E('aerobic','英 /eəˈrəʊbɪk/；美 /erˈroʊbɪk/','有氧的；需氧的；有氧运动的','原来讲生物生活离不开氧，后来也用来讲以有氧供能为主的运动。','近源法语 aérobie，加英语 -ic；法语词由空气 aer 与生命 bios 的希腊材料构成，不是一个古希腊健身术语。',B+[['英语 aerobic 的运动用法','与运动中的氧利用相关']],'aerobic bacteria 是需氧细菌；aerobic exercise 是有氧运动。词源里的空气不能直接代替现代生物学里的氧：空气含有多种气体，这个术语重点说氧的参与。','aerobic bacteria；aerobic respiration；aerobic exercise；aerobic capacity。','aerobic 与 anaerobic 的区别在氧是否参与相应生理或代谢过程，不是运动时张不张嘴呼吸。',('The lesson compares aerobic and anaerobic respiration.','这节课比较有氧呼吸和无氧呼吸。'),('The sports center offers several kinds of aerobic exercise.','运动中心提供几种有氧运动项目。'),sources=['https://www.etymonline.com/word/aerobic','https://www.merriam-webster.com/dictionary/aerobic']),
E('aerobics','英 /əˈrəʊbɪks/；美 /əˈroʊbɪks/','有氧健身运动；健美操','想象一群人跟着节奏持续活动身体；日常常指这样的健身课程。','来自 aerobic，采用 -ics 这一活动或学科名称形式；名称由 Kenneth Cooper 的 1968 年同名著作推广。',B+[['aerobic → aerobics','有氧活动 → 一套有氧健身运动及相关课程']],'an aerobics class 常是跟音乐做连续动作的健身课；water aerobics 是水中健身操。广义 aerobic exercise 的范围更大，不必每次都翻成健美操。','do aerobics；an aerobics class；water aerobics；an aerobics instructor。','aerobics 虽然以 s 结尾，作为活动名称一般按单数看：Aerobics is popular。它不是多个 aerobic 的复数。',('She goes to an aerobics class on Saturday mornings.','她每周六上午去上健美操课。'),('Water aerobics is one of the activities offered at the pool.','水中健身操是游泳馆提供的活动之一。'),sources=['https://www.etymonline.com/word/aerobic','https://www.merriam-webster.com/dictionary/aerobics']),
E('aerobically','英 /eəˈrəʊbɪkli/；美 /erˈroʊbɪkli/','在有氧条件下；以有氧方式','给动作加上条件：这个生长、分解或供能过程用到了氧。','aerobic + -ally；-ic 后的副词结尾常写 -ically，读音通常压成 /ɪkli/。',B+[['aerobic + -ally → aerobically','有氧的 → 在有氧条件下进行']],'grow aerobically 是在有氧条件下生长；break down aerobically 是通过有氧过程分解。它修饰动作，帮助说明过程如何发生，不是把 aerobic 的字母照念一遍。','grow aerobically；respire aerobically；decompose aerobically。','aerobically 是副词；aerobic 是形容词：aerobic growth 对应 grow aerobically。',('The bacteria were grown aerobically in the laboratory.','这些细菌在实验室的有氧条件下培养。'),('The report explains how organic material decomposes aerobically.','报告解释了有机物如何在有氧条件下分解。'),sources=['https://www.merriam-webster.com/dictionary/aerobic','https://en.wiktionary.org/wiki/aerobically']),
E('anaerobically','英 /ˌænəˈrəʊbɪkli/；美 /ˌænəˈroʊbɪkli/','在无氧条件下；以无氧方式','把氧这一条件拿掉，描述仍能进行的相应代谢过程。','anaerobic + -ally；其中 an- 表否定，aerobic 表有氧相关。不要把开头误读成另一个 ana- 向上。',[['希腊 an- 无 + aer 空气 + bios 生命','近代术语的构词材料'],['anaerobic → anaerobically','无氧的 → 在无氧条件下进行']],'digest material anaerobically 是在无氧条件下分解材料，常见于处理有机物、产生沼气等介绍。这个词说明反应或代谢条件，不表示人必须屏住呼吸。','grow anaerobically；digest anaerobically；produce energy anaerobically。','an- 是否定前缀，与 analysis 中表示分开等意义的 ana- 不同。看到相同字母，不应自动归为同一个前缀。',('The waste is digested anaerobically in a sealed tank.','这些废料在密闭罐中进行无氧消化处理。'),('The experiment compared cultures grown aerobically and anaerobically.','实验比较了在有氧与无氧条件下培养的培养物。'),sources=['https://www.merriam-webster.com/dictionary/anaerobic','https://en.wiktionary.org/wiki/anaerobically'])
]
